//! Parity gate: assert every case recorded by the Python oracle matches the Rust
//! seal construction and verification order exactly.
//!
//! The fixture is generated by `tests/parity_oracle.py`, which runs the real
//! `ezchain_core.ledger` code under the project venv and records, for each case:
//! the canonical payload bytes of every link, the chained head, the recorded seal
//! and the typed refusal code Python's verify order reports. This test feeds the
//! canonical lexemes to Rust and requires identical payload bytes, identical
//! digests and identical typed refusal codes. A failure here is a parity failure,
//! not a test bug: do not edit the fixture — fix the implementation and regenerate.

use ezchain_seal::{
    chain_payload, digest_entries, ledger_digest, seal_entries, verify_seal, LedgerEntry,
    LedgerSeal,
};

const FIXTURE: &str = include_str!("parity_fixture.txt");

/// Decode lowercase hex (accept either case) into bytes.
fn decode_hex(text: &str) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(text.len() / 2);
    let (pairs, rest) = text.as_bytes().as_chunks::<2>();
    assert!(rest.is_empty(), "odd-length hex in fixture: {text:?}");
    for pair in pairs {
        let high = (pair[0] as char).to_digit(16).expect("hex digit") as u8;
        let low = (pair[1] as char).to_digit(16).expect("hex digit") as u8;
        bytes.push(high * 16 + low);
    }
    bytes
}

/// Decode one fixture field: `N` is None, `S<hex>` is Some(UTF-8 text).
fn decode_field(field: &str) -> Option<String> {
    match field {
        "N" => None,
        _ => {
            let hex = field.strip_prefix('S').expect("field must be N or S<hex>");
            Some(String::from_utf8(decode_hex(hex)).expect("field is UTF-8"))
        }
    }
}

fn decode_entry(field: &str) -> LedgerEntry {
    let parts: Vec<&str> = field.split(',').collect();
    assert_eq!(parts.len(), 11, "an entry has exactly 11 fields: {field:?}");
    let mut fields = parts.into_iter().map(decode_field);
    let mut next = || fields.next().expect("11 fields");
    LedgerEntry {
        account: next().expect("account is always Some"),
        asset: next().expect("asset is always Some"),
        amount: next().expect("amount is always Some"),
        usd_value: next().expect("usd_value is always Some"),
        kind: next().expect("kind is always Some"),
        group_id: next(),
        created_at: next(),
        wallet_id: next(),
        bucket_id: next(),
        actor_kind: next(),
        actor_id: next(),
    }
}

fn decode_list(field: &str) -> Vec<&str> {
    if field == "-" {
        Vec::new()
    } else {
        field.split(';').collect()
    }
}

#[test]
fn python_oracle_parity() {
    let mut passed = 0usize;
    let mut failures: Vec<String> = Vec::new();

    for (index, line) in FIXTURE.lines().enumerate() {
        let f: Vec<&str> = line.split('\t').collect();
        assert_eq!(f.len(), 10, "malformed fixture line {}", index + 1);
        let (
            name,
            previous,
            prev_head,
            seal_count,
            seal_head,
            verify_count,
            verify_head,
            expected_code,
            payload_hexes,
            entries_field,
        ) = (f[0], f[1], f[2], f[3], f[4], f[5], f[6], f[7], f[8], f[9]);

        let entries: Vec<LedgerEntry> = decode_list(entries_field)
            .into_iter()
            .map(decode_entry)
            .collect();
        let payloads: Vec<Vec<u8>> = decode_list(payload_hexes)
            .into_iter()
            .map(decode_hex)
            .collect();

        let mut problems: Vec<String> = Vec::new();

        // Byte-level parity of every canonical chain payload.
        if payloads.len() != entries.len() {
            problems.push(format!(
                "payload count {} != entry count {}",
                payloads.len(),
                entries.len()
            ));
        } else {
            for (i, (entry, expected)) in entries.iter().zip(payloads.iter()).enumerate() {
                let actual = chain_payload(i + 1, entry);
                if actual.as_bytes() != expected.as_slice() {
                    problems.push(format!(
                        "payload {} differs: expected {}, got {}",
                        i + 1,
                        String::from_utf8_lossy(expected),
                        actual
                    ));
                }
            }
        }

        // Digest parity: genesis fold, custom-predecessor fold and recorded seal.
        let seal = seal_entries(&entries);
        let expected_count: usize = seal_count.parse().expect("count is decimal");
        if seal.count() != expected_count {
            problems.push(format!("seal count {} != {expected_count}", seal.count()));
        }
        if seal.head() != seal_head {
            problems.push(format!("seal head {} != {seal_head}", seal.head()));
        }
        if digest_entries(&entries) != seal_head {
            problems.push("digest_entries head mismatch".to_string());
        }
        if ledger_digest(&entries, previous) != prev_head {
            problems.push(format!(
                "ledger_digest(previous={previous}) head mismatch, expected {prev_head}"
            ));
        }

        // Verify-order parity: same typed refusal code as Python.
        let recorded = LedgerSeal::new(
            verify_count.parse::<usize>().expect("count is decimal"),
            verify_head,
        );
        let actual_code = match verify_seal(&entries, &recorded) {
            Ok(()) => "OK",
            Err(error) => error.code(),
        };
        if actual_code != expected_code {
            problems.push(format!("verify code {actual_code} != {expected_code}"));
        }

        if problems.is_empty() {
            passed += 1;
        } else {
            failures.push(format!(
                "line {} [{name}]: {}",
                index + 1,
                problems.join("; ")
            ));
        }
    }

    let total = FIXTURE.lines().count();
    assert!(total > 0, "empty oracle fixture");
    eprintln!("parity: {passed}/{total} cases match the Python oracle");
    if !failures.is_empty() {
        for failure in failures.iter().take(20) {
            eprintln!("  MISMATCH {failure}");
        }
        panic!("{} parity case(s) failed", failures.len());
    }
}

#[test]
fn fixture_has_the_expected_mix_of_typed_refusals() {
    let mut ok = 0usize;
    let mut count = 0usize;
    let mut head = 0usize;
    for line in FIXTURE.lines() {
        let code = line.split('\t').nth(7).expect("code field");
        match code {
            "OK" => ok += 1,
            "CountMismatch" => count += 1,
            "HeadMismatch" => head += 1,
            other => panic!("unknown refusal code in fixture: {other}"),
        }
    }
    assert!(
        ok > 0 && count > 0 && head > 0,
        "fixture must cover all codes"
    );
    eprintln!("fixture: ok={ok}, count_mismatch={count}, head_mismatch={head}");
}
